source(file.path(commandArgs(TRUE)[1],'code/common.R'));suppressPackageStartupMessages(library(Banksy));f<-file.path(out,'tmp/knn.rds');if(file.exists(f))quit(save='no');co<-fread(file.path(out,'coordinates.tsv.gz'));sm<-fread(file.path(out,'spatial_metadata.tsv.gz'));stopifnot(identical(co$bin_id,sm$bin_id));xy<-as.matrix(co[,.(x_um,y_um)]);groups<-split(seq_len(nrow(co)),sm$spatial_component);edges<-vector('list',length(groups));summ<-list();for(i in seq_along(groups)){idx<-groups[[i]];k<-min(50L,length(idx)-1L);cat('NEIGHBORS',s,i,length(groups),length(idx),k,'\n');if(k==0){z<-data.table(from=1L,to=1L,weight=1,phi=0);dist<-0}else{z<-Banksy:::computeNeighbors(xy[idx,,drop=FALSE],spatial_mode='kNN_median',k_geom=k,n=2,sigma=1.5,alpha=.05,k_spatial=10,verbose=FALSE);dist<-sqrt(rowSums((xy[idx[z$from],,drop=FALSE]-xy[idx[z$to],,drop=FALSE])^2))};stats<-data.table(from=idx[z$from],distance=dist)[,.(neighbor_n=if(k==0)0L else .N,kernel_support_n=.N,neighbor_min_um=min(distance),neighbor_max_um=max(distance),neighbor_median_um=median(distance)),by=from];stats[,singleton_fallback:=k==0];summ[[i]]<-stats;z[,from:=idx[from]];z[,to:=idx[to]];edges[[i]]<-z};e<-rbindlist(edges);stats<-rbindlist(summ);setorder(stats,from);stopifnot(identical(stats$from,seq_len(nrow(co))),all(sm$spatial_component[e$from]==sm$spatial_component[e$to]));stats[,bin_id:=co$bin_id];stats[,from:=NULL];fwrite(stats,file.path(out,'neighbor_statistics.tsv.gz'),sep='\t');saveRDS(e,f,compress=FALSE);write_json(list(Banksy=as.character(packageVersion('Banksy')),package_path=find.package('Banksy'),k_geom=50,weight='exp(-d^2 / median(d)^2), normalized per target, excludes self except singleton fallback',components=length(groups),actual_max_distance_quantiles=quantile(stats$neighbor_max_um,c(0,.5,.9,.95,.99,1)),n_small_neighbor= sum(stats$neighbor_n<50),n_singleton=sum(stats$singleton_fallback),cross_component_edges=0,split_scale=FALSE),file.path(out,'neighbor_summary.json'),auto_unbox=TRUE,pretty=TRUE,digits=NA);cat('NEIGHBORS_COMPLETE',s,'\n')
